ull, "description": "本批《资治通鉴》与二十四史所见人物：董光嗣，董之子、自杀者。", "biography": null, "status": "draft", "id": "75b448d8-e3b0-504b-8e25-119b41792218"}, {"name": "潘稠", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：潘稠，指挥使、率十卒斩董者。", "biography": null, "status": "draft", "id": "d719adc5-4576-5d24-99b6-f40911037601"}, {"name": "康福", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：康福。", "biography": null, "status": "draft", "id": "7419fd99-6e0a-53d2-8c35-3a4c51f654d7"}, {"name": "王处回", "aliases": ["王處回"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王处回，为税官请免的中门副使。", "biography": null, "status": "draft", "id": "159fd2b3-759b-522a-a971-11356c6fe970"}, {"name": "李仁罕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李仁罕。", "biography": null, "status": "draft", "id": "7059bea3-bcb1-5a3a-9891-bd820251d3d8"}, {"name": "迭罗卿", "aliases": ["迭羅卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：迭罗卿，契丹使者、辞归者。", "biography": null, "status": "draft", "id": "cda05b41-54a7-5386-ac98-427736092700"}, {"name": "李嗣源", "aliases": ["李亶", "后唐明宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "biography": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "status": "draft", "id": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"name": "荝骨舍利", "aliases": ["則骨舍利", "则骨舍利"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：荝骨舍利，本次获归的被留者。", "biography": null, "status": "draft", "id": "e4e94094-cae4-5f1e-9da0-917e7152b794"}, {"name": "荝剌", "aliases": ["萴剌", "則剌", "则剌", "原知感"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：荝剌，前已被留在后唐，契丹屡请归的将领。", "biography": null, "status": "draft", "id": "755daf3d-2f6b-5807-87ec-930fea729b93"}, {"name": "王彦铢", "aliases": ["王彥銖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：王彦铢，客将、奉孟示意执李严下斩者。", "biography": null, "status": "draft", "id": "8fe89798-6ba7-5df8-bd44-a5cd5847aa62"}, {"name": "王思同", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“王思同、李承约等离开幽州投奔河东”中为归附者。", "biography": null, "status": "draft", "id": "55aef39e-fd58-5b12-bda5-cbbf0bbba77e"}, {"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：范延光。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "李存瑰", "aliases": ["李瓌", "李瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李存瑰，供奉官、赴西川赐诏者。", "biography": null, "status": "draft", "id": "a91449a7-a285-52aa-9c4a-0bf81e533f51"}, {"name": "李克宁", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：李克宁。", "biography": null, "status": "draft", "id": "91749ebc-db3b-5153-a45f-0959306567a4"}, {"name": "王延钧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明三年条所见人物：王延钧。", "biography": null, "status": "draft", "id": "5be92fdd-884d-5ecb-b627-4f46ac442676"}, {"name": "陈守元", "aliases": ["陳守元"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈守元，道士、劝建宫者。", "biography": null, "status": "draft", "id": "5df7e840-5673-57f7-83d7-ba3228fe2d3c"}, {"name": "徐彦", "aliases": ["徐彥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐彦，巫者、劝建宫者。", "biography": null, "status": "draft", "id": "c04e4f74-3ce3-5d78-873d-0a5a875827ee"}]'::jsonb)
